import{_ as l,a0 as p,w as s,s as u,I as i,a1 as r,A as o,x as t,ao as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"Manjaro 18.1（KDE）安装图解 | LCTT x X-CMD","titleTemplate":false,"description":"Manjaro 18.1（KDE）安装图解 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Manjaro 18.1（KDE）安装图解 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Manjaro 18.1（KDE）安装图解 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190923 Installation Guide of Manjaro 18.1 (KDE Edition) with Screenshots","title":"Manjaro 18.1（KDE）安装图解","tag":"201910","desc":""},"relativePath":"201910/20190923 Installation Guide of Manjaro 18.1 (KDE Edition) with Screenshots.md","filePath":"[post].md"}'),d={name:"201910/20190923 Installation Guide of Manjaro 18.1 (KDE Edition) with Screenshots.md"};function h(m,a,w,j,c,b){const n=p("Link");return s(),u("div",null,[i("p",null,[r(n,{href:"collector:",title:"lujun9972"},{default:o(()=>[...a[0]||(a[0]=[t("#",-1)])]),_:1}),a[5]||(a[5]=t(": subject: (Installation Guide of Manjaro 18.1 (KDE Edition) with Screenshots) ",-1)),r(n,{href:"collector:",title:"lujun9972"},{default:o(()=>[...a[1]||(a[1]=[t("#",-1)])]),_:1}),a[6]||(a[6]=t(": via: (",-1)),r(n,{href:"https://www.linuxtechi.com/install-manjaro-18-1-kde-edition-screenshots/"},{default:o(()=>[...a[2]||(a[2]=[t("https://www.linuxtechi.com/install-manjaro-18-1-kde-edition-screenshots/",-1)])]),_:1}),a[7]||(a[7]=t(") ",-1)),r(n,{href:"collector:",title:"lujun9972"},{default:o(()=>[...a[3]||(a[3]=[t("#",-1)])]),_:1}),a[8]||(a[8]=t(": author: (Pradeep Kumar ",-1)),r(n,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:o(()=>[...a[4]||(a[4]=[t("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),a[9]||(a[9]=t(")",-1))]),a[28]||(a[28]=e('<h1 id="manjaro-18-1-kde-安装图解" tabindex="-1">Manjaro 18.1（KDE）安装图解 <a class="header-anchor" href="#manjaro-18-1-kde-安装图解" aria-label="Permalink to “Manjaro 18.1（KDE）安装图解”">​</a></h1><p>在 Manjaro 18.0（Illyria）发布一年之际，该团队发布了他们的下一个重要版本，即 Manjaro 18.1，代号为 “Juhraya”。该团队还发布了一份官方声明，称 Juhraya 包含了许多改进和错误修复。</p><h3 id="manjaro-18-1-中的新功能" tabindex="-1">Manjaro 18.1 中的新功能 <a class="header-anchor" href="#manjaro-18-1-中的新功能" aria-label="Permalink to “Manjaro 18.1 中的新功能”">​</a></h3><p>以下列出了 Manjaro 18.1 中的一些新功能和增强功能：</p><ul><li>可以在 LibreOffice 或 Free Office 之间选择</li><li>Xfce 版的新 Matcha 主题</li><li>在 KDE 版本中重新设计了消息传递系统</li><li>使用 bhau 工具支持 Snap 和 FlatPak 软件包</li></ul><h3 id="最小系统需求" tabindex="-1">最小系统需求 <a class="header-anchor" href="#最小系统需求" aria-label="Permalink to “最小系统需求”">​</a></h3><ul><li>1 GB RAM</li><li>1 GHz 处理器</li><li>大约 30 GB 硬盘空间</li><li>互联网连接</li><li>启动介质（USB/DVD）</li></ul><h3 id="安装-manjaro-18-1-kde-版-的分步指南" tabindex="-1">安装 Manjaro 18.1（KDE 版）的分步指南 <a class="header-anchor" href="#安装-manjaro-18-1-kde-版-的分步指南" aria-label="Permalink to “安装 Manjaro 18.1（KDE 版）的分步指南”">​</a></h3><p>要在系统中开始安装 Manjaro 18.1（KDE 版），请遵循以下步骤：</p><h4 id="步骤-1-下载-manjaro-18-1-iso" tabindex="-1">步骤 1) 下载 Manjaro 18.1 ISO <a class="header-anchor" href="#步骤-1-下载-manjaro-18-1-iso" aria-label="Permalink to “步骤 1) 下载 Manjaro 18.1 ISO”">​</a></h4>',10)),i("p",null,[a[11]||(a[11]=t("在安装之前，你需要从位于 ",-1)),r(n,{href:"https://manjaro.org/download/official/kde/"},{default:o(()=>[...a[10]||(a[10]=[t("这里",-1)])]),_:1}),a[12]||(a[12]=t(" 的官方下载页面下载 Manjaro 18.1 的最新副本。由于我们这里介绍的是 KDE 版本，因此我们选择 KDE 版本。但是对于所有桌面环境（包括 Xfce、KDE 和 Gnome 版本），安装过程都是相同的。",-1))]),a[29]||(a[29]=e('<h4 id="步骤-2-创建-usb-启动盘" tabindex="-1">步骤 2) 创建 USB 启动盘 <a class="header-anchor" href="#步骤-2-创建-usb-启动盘" aria-label="Permalink to “步骤 2) 创建 USB 启动盘”">​</a></h4><p>从 Manjaro 下载页面成功下载 ISO 文件后，就可以创建 USB 磁盘了。将下载的 ISO 文件复制到 USB 磁盘中，然后创建可引导磁盘。确保将你的引导设置更改为使用 USB 引导，并重新启动系统。</p><h4 id="步骤-3-manjaro-live-版安装环境" tabindex="-1">步骤 3) Manjaro Live 版安装环境 <a class="header-anchor" href="#步骤-3-manjaro-live-版安装环境" aria-label="Permalink to “步骤 3) Manjaro Live 版安装环境”">​</a></h4><p>系统重新启动时，它将自动检测到 USB 驱动器，并开始启动进入 Manjaro Live 版安装屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Boot-Manjaro-18-1-kde-installation.jpg" alt="Boot-Manjaro-18-1-kde-installation"></p><p>接下来，使用箭头键选择 “<ruby>启动：Manjaro x86_64 kde<rt>Boot: Manjaro x86_64 kde</rt></ruby>”，然后按回车键以启动 Manjaro 安装程序。</p><h4 id="安装-4-选择启动安装程序" tabindex="-1">安装 4) 选择启动安装程序 <a class="header-anchor" href="#安装-4-选择启动安装程序" aria-label="Permalink to “安装 4) 选择启动安装程序”">​</a></h4><p>接下来，将启动 Manjaro 安装程序，如果你已连接到互联网，Manjaro 将自动检测你的位置和时区。单击 “<ruby>启动安装程序<rt>Launch Installer</rt></ruby>”，开始在系统中安装 Manjaro 18.1 KDE 版本。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Choose-Launch-Installaer-Manjaro18-1-kde.jpg" alt="Choose-Launch-Installaer-Manjaro18-1-kde"></p><h4 id="步骤-5-选择语言" tabindex="-1">步骤 5) 选择语言 <a class="header-anchor" href="#步骤-5-选择语言" aria-label="Permalink to “步骤 5) 选择语言”">​</a></h4><p>接下来，安装程序将带你选择你的首选语言。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Choose-Language-Manjaro18-1-Kde-Installation.jpg" alt="Choose-Language-Manjaro18-1-Kde-Installation"></p><p>选择你想要的语言，然后单击“<ruby>下一步<rt>Next</rt></ruby>”。</p><h4 id="步骤-6-选择时区和区域" tabindex="-1">步骤 6) 选择时区和区域 <a class="header-anchor" href="#步骤-6-选择时区和区域" aria-label="Permalink to “步骤 6) 选择时区和区域”">​</a></h4><p>在下一个屏幕中，选择所需的时区和区域，然后单击“<ruby>下一步<rt>Next</rt></ruby>”继续。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Select-Location-During-Manjaro18-1-KDE-Installation.jpg" alt="Select-Location-During-Manjaro18-1-KDE-Installation"></p><h4 id="步骤-7-选择键盘布局" tabindex="-1">步骤 7) 选择键盘布局 <a class="header-anchor" href="#步骤-7-选择键盘布局" aria-label="Permalink to “步骤 7) 选择键盘布局”">​</a></h4><p>在下一个屏幕中，选择你喜欢的键盘布局，然后单击“<ruby>下一步<rt>Next</rt></ruby>”继续。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Select-Keyboard-Layout-Manjaro18-1-kde-installation.jpg" alt="Select-Keyboard-Layout-Manjaro18-1-kde-installation"></p><h4 id="步骤-8-选择分区类型" tabindex="-1">步骤 8) 选择分区类型 <a class="header-anchor" href="#步骤-8-选择分区类型" aria-label="Permalink to “步骤 8) 选择分区类型”">​</a></h4><p>这是安装过程中非常关键的一步。 它将允许你选择分区方式：</p><ul><li>擦除磁盘</li><li>手动分区</li><li>并存安装</li><li>替换分区</li></ul><p>如果在 VM（虚拟机）中安装 Manjaro 18.1，则将看不到最后两个选项。</p><p>如果你不熟悉 Manjaro Linux，那么我建议你使用第一个选项（<ruby>擦除磁盘<rt>Erase Disk</rt></ruby>），它将为你自动创建所需的分区。如果要创建自定义分区，则选择第二个选项“<ruby>手动分区<rt>Manual Partitioning</rt></ruby>”，顾名思义，它将允许我们创建自己的自定义分区。</p><p>在本教程中，我将通过选择“<ruby>手动分区<rt>Manual Partitioning</rt></ruby>”选项来创建自定义分区：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Manual-Partition-Manjaro18-1-KDE.jpg" alt="Manual-Partition-Manjaro18-1-KDE"></p><p>选择第二个选项，然后单击“<ruby>下一步<rt>Next</rt></ruby>”继续。</p><p>如我们所见，我有 40 GB 硬盘，因此我将在其上创建以下分区，</p><ul><li><code>/boot</code>       –  2GB（ext4）</li><li><code>/</code>           –  10 GB（ext4）</li><li><code>/home</code>      –  22 GB（ext4）</li><li><code>/opt</code>       –  4 GB（ext4）</li><li><ruby>交换分区<rt>Swap</rt></ruby>     –  2 GB</li></ul><p>当我们在上方窗口中单击“<ruby>下一步<rt>Next</rt></ruby>”时，将显示以下屏幕，选择“<ruby>新建分区表<rt>new partition table</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Create-Partition-Table-Manjaro18-1-Installation.jpg" alt="Create-Partition-Table-Manjaro18-1-Installation"></p><p>点击“<ruby>确定<rt>OK</rt></ruby>”。</p><p>现在选择可用空间，然后单击“<ruby>创建<rt>create</rt></ruby>”以将第一个分区设置为大小为 2 GB 的 <code>/boot</code>，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/boot-partition-manjaro-18-1-installation.jpg" alt="boot-partition-manjaro-18-1-installation"></p><p>单击“<ruby>确定<rt>OK</rt></ruby>”以继续操作，在下一个窗口中再次选择可用空间，然后单击“<ruby>创建<rt>create</rt></ruby>”以将第二个分区设置为 <code>/</code>，大小为 10 GB：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/slash-root-partition-manjaro18-1-installation.jpg" alt="slash-root-partition-manjaro18-1-installation"></p><p>同样，将下一个分区创建为大小为 22 GB 的 <code>/home</code>：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/home-partition-manjaro18-1-installation.jpg" alt="home-partition-manjaro18-1-installation"></p><p>到目前为止，我们已经创建了三个分区作为主分区，现在创建下一个分区作为扩展分区：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Extended-Partition-Manjaro18-1-installation.jpg" alt="Extended-Partition-Manjaro18-1-installation"></p><p>单击“<ruby>确定<rt>OK</rt></ruby>”以继续。</p><p>创建大小分别为 5 GB 和 2 GB 的 <code>/opt</code> 和交换分区作为逻辑分区。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/opt-partition-manjaro-18-1-installation.jpg" alt="opt-partition-manjaro-18-1-installation"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/swap-partition-manjaro18-1-installation.jpg" alt="swap-partition-manjaro18-1-installation"></p><p>完成所有分区的创建后，单击“<ruby>下一步<rt>Next</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/choose-next-after-partition-creation.jpg" alt="choose-next-after-partition-creation"></p><h4 id="步骤-9-提供用户信息" tabindex="-1">步骤 9) 提供用户信息 <a class="header-anchor" href="#步骤-9-提供用户信息" aria-label="Permalink to “步骤 9) 提供用户信息”">​</a></h4><p>在下一个屏幕中，你需要提供用户信息，包括你的姓名、用户名、密码、计算机名等：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/User-creation-details-manjaro18-1-installation.jpg" alt="User-creation-details-manjaro18-1-installation"></p><p>提供所有信息后，单击“<ruby>下一步<rt>Next</rt></ruby>”继续安装。</p><p>在下一个屏幕中，系统将提示你选择办公套件，因此请做出适合你的选择：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Office-Suite-Selection-Manjaro18-1.jpg" alt="Office-Suite-Selection-Manjaro18-1"></p><p>单击“<ruby>下一步<rt>Next</rt></ruby>”以继续。</p><h4 id="步骤-10-摘要信息" tabindex="-1">步骤 10) 摘要信息 <a class="header-anchor" href="#步骤-10-摘要信息" aria-label="Permalink to “步骤 10) 摘要信息”">​</a></h4><p>在完成实际安装之前，安装程序将向你显示你选择的所有详细信息，包括语言、时区、键盘布局和分区信息等。单击“<ruby>安装<rt>Install</rt></ruby>”以继续进行安装过程。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Summary-manjaro18-1-installation.jpg" alt="Summary-manjaro18-1-installation"></p><h4 id="步骤-11-进行安装" tabindex="-1">步骤 11) 进行安装 <a class="header-anchor" href="#步骤-11-进行安装" aria-label="Permalink to “步骤 11) 进行安装”">​</a></h4><p>现在，实际的安装过程开始，一旦完成，请重新启动系统以登录到 Manjaro 18.1 KDE 版：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Manjaro18-1-Installation-Progress.jpg" alt="Manjaro18-1-Installation-Progress"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Restart-Manjaro-18-1-after-installation.jpg" alt="Restart-Manjaro-18-1-after-installation"></p><h4 id="步骤-12-安装成功后登录" tabindex="-1">步骤 12) 安装成功后登录 <a class="header-anchor" href="#步骤-12-安装成功后登录" aria-label="Permalink to “步骤 12) 安装成功后登录”">​</a></h4><p>重新启动后，我们将看到以下登录屏幕，使用我们在安装过程中创建的用户凭据登录：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Login-screen-after-manjaro-18-1-installation.jpg" alt="Login-screen-after-manjaro-18-1-installation"></p><p>点击“<ruby>登录<rt>Login</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/KDE-Desktop-Screen-Manjaro-18-1.jpg" alt="KDE-Desktop-Screen-Manjaro-18-1"></p><p>就是这样！你已经在系统中成功安装了 Manjaro 18.1 KDE 版，并探索了所有令人兴奋的功能。请在下面的评论部分中发表你的反馈和建议。</p><hr>',67)),i("p",null,[a[14]||(a[14]=t("via: ",-1)),r(n,{href:"https://www.linuxtechi.com/install-manjaro-18-1-kde-edition-screenshots/"},{default:o(()=>[...a[13]||(a[13]=[t("https://www.linuxtechi.com/install-manjaro-18-1-kde-edition-screenshots/",-1)])]),_:1})]),i("p",null,[a[19]||(a[19]=t("作者：",-1)),r(n,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:o(()=>[...a[15]||(a[15]=[t("Pradeep Kumar",-1)])]),_:1}),a[20]||(a[20]=t(" 选题：",-1)),r(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...a[16]||(a[16]=[t("lujun9972",-1)])]),_:1}),a[21]||(a[21]=t(" 译者：",-1)),r(n,{href:"https://github.com/wxy"},{default:o(()=>[...a[17]||(a[17]=[t("wxy",-1)])]),_:1}),a[22]||(a[22]=t(" 校对：",-1)),r(n,{href:"https://github.com/wxy"},{default:o(()=>[...a[18]||(a[18]=[t("wxy",-1)])]),_:1})]),i("p",null,[a[25]||(a[25]=t("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[23]||(a[23]=[t("LCTT",-1)])]),_:1}),a[26]||(a[26]=t(" 原创编译，",-1)),r(n,{href:"https://linux.cn/"},{default:o(()=>[...a[24]||(a[24]=[t("Linux中国",-1)])]),_:1}),a[27]||(a[27]=t(" 荣誉推出",-1))])])}const g=l(d,[["render",h]]);export{M as __pageData,g as default};
